mapper.sql:
from sys_role r
where r.del_flag = '0'

    AND r.role_id = #{role.roleId}


    AND r.role_name like concat('%', #{role.roleName}, '%')


    AND r.status = #{role.status}


    AND r.role_key like concat('%', #{role.roleKey}, '%')


    AND r.is_team_role = #{role.isTeamRole}


    AND r.is_project_role = #{role.isProjectRole}

SELECT DISTINCT r.role_id, r.role_name, r.role_name_i18n_key, r.role_key, r.role_sort, r.data_scope, r.menu_check_strictly, r.dept_check_strictly, r.status, r.remark, r.is_team_role, r.is_project_role FROM sys_role r LEFT JOIN ( SELECT 'system' AS src, NULL AS src_id, user_id, role_id FROM sys_user_role
UNION SELECT 'team' AS src, ut.team_id AS src_id, ut.user_id, utr.role_id FROM sys_user_team_role utr LEFT JOIN sys_user_team ut ON ut.user_team_id = utr.user_team_id AND ut.team_id = #{teamId}
UNION SELECT 'project' AS src, up.project_id AS src_id, up.user_id, upr.role_id FROM sys_user_project_role upr LEFT JOIN sys_user_project up ON up.user_project_id = upr.user_project_id AND up.project_id = #{projectId}
) ur ON ur.role_id = r.role_id LEFT JOIN sys_user u ON u.user_id = ur.user_id

mapper.update:
update sys_role
role_name = #{roleName}, role_name_i18n_key = #{roleNameI18nKey}, role_key = #{roleKey}, role_sort = #{roleSort}, data_scope = #{dataScope}, menu_check_strictly = #{menuCheckStrictly}, dept_check_strictly = #{deptCheckStrictly}, status = #{status}, remark = #{remark}, is_team_role = #{isTeamRole}, is_project_role = #{isProjectRole}, update_by = #{updateBy}, update_time = NOW()
where role_id = #{roleId}
